const $=s=>document.querySelector(s);
const icons={calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2m4 0h2"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',check:'<path d="m8 12 3 3 6-7"/><rect x="3" y="3" width="18" height="18" rx="5"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',down:'<path d="m7 10 5 5 5-5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',leaf:'<path d="M19 4C9 2 2 8 6 15s15 1 13-11ZM6 20l9-11"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',cloud:'<path d="M6 18a5 5 0 1 1 1-10 6 6 0 0 1 11 2 4 4 0 0 1 0 8Z"/><path d="m9 13 2 2 4-4"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l3 3h6a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.calendar}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=new Date();today.setHours(0,0,0,0);
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fromKey=s=>new Date(s+'T00:00:00');
const monthName=d=>d.toLocaleDateString('en-US',{month:'long',year:'numeric'});
const formatDate=s=>fromKey(s).toLocaleDateString('en-US',{month:'short',day:'numeric'});
const uid=()=>crypto.randomUUID();
let viewed=new Date(today.getFullYear(),today.getMonth(),1),selected=dateKey(today),view='year',filter=null,nav='calendar';
const defaultProjects=[{id:'studio',name:'Studio work',color:'#a995c8',tone:'purple'},{id:'personal',name:'Personal',color:'#9eb589',tone:'green'},{id:'growth',name:'Learning & growth',color:'#d3a374',tone:'orange'},{id:'life',name:'Life admin',color:'#89a9b6',tone:'blue'}];
function demoTasks(){const key=n=>dateKey(new Date(viewed.getFullYear(),viewed.getMonth(),n));const make=(title,day,project,time='',scope='day',done=false)=>({id:uid(),title,date:key(day),project,time,scope,done});const d=today.getDate();return [make('Set intentions for the month',1,'personal','','month'),make('Make space for a personal project',1,'growth','','month'),make('Brand direction & moodboard',3,'studio','10:00'),make('A little reading, every day',5,'growth','18:00'),make('Website exploration',9,'studio','09:00'),make('Plan a weekend outdoors',12,'personal'),make('Weekly reset & reflection',14,'personal','','week'),make('Design a little, dream a lot',d,'studio','09:00'),make('A walk. No headphones.',d,'personal','12:30'),make('Learn something new',d,'growth','16:00'),make('Project check-in',Math.min(20,d+2),'studio','11:00'),make('Wrap up the loose ends',25,'life','10:00'),make('Make time for good company',27,'personal','19:00'),make('Reflect, reset, begin again',28,'growth','','week')];}
let data;try{data=JSON.parse(localStorage.getItem('tempo-v1'))}catch{}if(!data||!Array.isArray(data.tasks)||!Array.isArray(data.projects))data={projects:defaultProjects,tasks:demoTasks()};
function save(){try{localStorage.setItem('tempo-v1',JSON.stringify(data))}catch{toast('Storage is full. Your latest changes may not persist.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
const project=id=>data.projects.find(p=>p.id===id)||data.projects[0];
const visible=t=>!filter||t.project===filter;
const monthTasks=()=>data.tasks.filter(t=>t.date.slice(0,7)===dateKey(viewed).slice(0,7)&&visible(t));
function taskHTML(t){const p=project(t.project);return `<div class="task-card ${esc(p.tone)} ${t.done?'done':''}" data-edit="${esc(t.id)}" tabindex="0" role="button" aria-label="Edit ${esc(t.title)}"><button class="check" data-toggle="${esc(t.id)}" aria-label="${t.done?'Mark incomplete':'Complete'}: ${esc(t.title)}">${t.done?'✓':''}</button><div class="task-copy"><div class="task-title">${esc(t.title)}</div><div class="task-meta"><span>${esc(p.name)} · ${t.scope==='month'?'This month':formatDate(t.date)}${t.time?' · '+displayTime(t.time):''}</span>${t.scope==='week'?'<span class="tag">Weekly</span>':''}</div></div></div>`}
function displayTime(s){const [h,m]=s.split(':').map(Number);return `${h%12||12}${m?':'+String(m).padStart(2,'0'):''} ${h<12?'am':'pm'}`}
function chapterHTML(i){const start=i*7+1,end=i===3?new Date(viewed.getFullYear(),viewed.getMonth()+1,0).getDate():start+6;const cur=today.getMonth()===viewed.getMonth()&&today.getFullYear()===viewed.getFullYear()&&today.getDate()>=start&&today.getDate()<=end;const tasks=monthTasks().filter(t=>t.scope!=='month'&&fromKey(t.date).getDate()>=start&&fromKey(t.date).getDate()<=end).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time));let dates='';for(let d=start;d<=end;d++){const dt=new Date(viewed.getFullYear(),viewed.getMonth(),d),k=dateKey(dt);dates+=`<button class="day-btn ${k===dateKey(today)?'today':''} ${k===selected?'selected':''} ${data.tasks.some(t=>t.date===k&&visible(t))?'has-events':''}" data-date="${k}" aria-label="${dt.toDateString()}"><small>${dt.toLocaleDateString('en-US',{weekday:'short'}).slice(0,2).toUpperCase()}</small><b>${d}</b></button>`}return `<section class="chapter ${cur?'current':''}"><div class="chapter-head"><div class="chapter-name"><span class="chapter-num">0${i+1}</span><div><h3>${['A fresh start','Find your flow','Make it happen','Bring it home'][i]}</h3><div class="chapter-sub">${viewed.toLocaleDateString('en-US',{month:'short'})} ${start}–${end} · ${tasks.length} ${tasks.length===1?'plan':'plans'}</div></div></div>${cur?'<span class="chapter-label">YOU ARE HERE</span>':`<button class="icon-btn" data-new="${dateKey(new Date(viewed.getFullYear(),viewed.getMonth(),start))}" aria-label="Add a task to chapter ${i+1}">${icon('plus')}</button>`}</div><div class="date-strip">${dates}</div><div class="chapter-tasks">${tasks.length?tasks.map(taskHTML).join(''):'<div class="empty-week">A little room for possibility.</div>'}</div><button class="add-chapter" data-new="${dateKey(new Date(viewed.getFullYear(),viewed.getMonth(),start))}">${icon('plus')} Add a plan</button></section>`}
function agendaHTML(){const tasks=data.tasks.filter(t=>t.date===selected&&t.scope!=='month'&&visible(t)).sort((a,b)=>a.time.localeCompare(b.time)),done=tasks.filter(t=>t.done).length,goals=monthTasks().filter(t=>t.scope==='month');return `<aside class="agenda"><div class="agenda-day"><div class="agenda-title"><h3>${selected===dateKey(today)?'Your day, at a glance':'A day in focus'}</h3>${icon('sun')}</div><div class="agenda-date">${fromKey(selected).toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}</div><div class="day-summary"><div class="summary-top"><span>${done} of ${tasks.length} plans complete</span><b>${tasks.length?Math.round(done/tasks.length*100):0}%</b></div><div class="progress"><div style="width:${tasks.length?done/tasks.length*100:0}%"></div></div></div><div class="timeline-label">The little things add up</div>${tasks.map(t=>`<div class="agenda-item"><time>${t.time?displayTime(t.time):'Anytime'}</time><div class="agenda-event ${esc(project(t.project).tone)}" data-edit="${t.id}" tabindex="0" role="button"><strong>${t.done?'✓ ':''}${esc(t.title)}</strong><span>${esc(project(t.project).name)}</span></div></div>`).join('')||'<div class="no-results">An open day. Make it yours.</div>'}<button class="agenda-add" data-new="${selected}">${icon('plus')} Add to this day</button></div><div class="monthly-focus"><div class="focus-top">The bigger picture<button class="icon-btn" id="add-goal" aria-label="Add a monthly goal">${icon('plus')}</button></div>${goals.map(t=>`<div class="focus-card" data-edit="${t.id}" tabindex="0" role="button"><strong>${t.done?'✓ ':''}${esc(t.title)}</strong><small><span class="dot" style="background:${esc(project(t.project).color)};width:5px;height:5px"></span> ${esc(project(t.project).name)} · Monthly goal</small></div>`).join('')||'<p class="tiny">What would make this month meaningful?</p>'}</div></aside>`}
function scheduleHTML(){if(view==='week')return weekHTML();const dt=fromKey(selected);let days='';if(view==='week'){const first=new Date(dt);first.setDate(dt.getDate()-((dt.getDay()+6)%7));for(let i=0;i<7;i++){const d=new Date(first);d.setDate(first.getDate()+i);days+=`<button class="${dateKey(d)===selected?'active':''}" data-date="${dateKey(d)}"><small>${d.toLocaleDateString('en-US',{weekday:'short'})}</small>${d.getDate()}</button>`}}const tasks=data.tasks.filter(t=>t.date===selected&&t.scope!=='month'&&visible(t));return `<div class="view-panel"><div class="view-heading"><h3>${dt.toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'})}</h3><button class="icon-btn" data-new="${selected}" aria-label="Add scheduled task">${icon('plus')}</button></div>${days?`<div class="week-days">${days}</div>`:''}${tasks.some(t=>!t.time)?`<div class="hour-row"><time>Anytime</time><div class="hour-items">${tasks.filter(t=>!t.time).map(taskHTML).join('')}</div></div>`:''}${Array.from({length:24},(_,h)=>`<div class="hour-row"><time>${displayTime(String(h).padStart(2,'0')+':00')}</time><div class="hour-items">${tasks.filter(t=>t.time&&Number(t.time.split(':')[0])===h).map(taskHTML).join('')||`<button class="hour-empty" data-hour="${String(h).padStart(2,'0')}:00">+ Add a plan</button>`}</div></div>`).join('')}</div>`}
function weekHTML(){const first=fromKey(selected);first.setDate(first.getDate()-((first.getDay()+6)%7));const days=Array.from({length:7},(_,i)=>{const d=new Date(first);d.setDate(first.getDate()+i);return d});const tasks=data.tasks.filter(t=>visible(t)&&t.date>=dateKey(first)&&t.date<=dateKey(days[6])&&t.scope!=='month');return `<div class="view-panel"><div class="view-heading"><h3>${formatDate(dateKey(first))} – ${formatDate(dateKey(days[6]))}</h3><span class="tiny">Your week, with a little breathing room.</span></div><div class="week-scroll"><div class="week-board">${days.map(d=>{const key=dateKey(d);return `<section class="week-column"><button class="week-column-head ${key===selected?'active':''}" data-date="${key}"><small>${d.toLocaleDateString('en-US',{weekday:'short'})}</small><b>${d.getDate()}</b>${key===dateKey(today)?'<span class="tiny">Today</span>':''}</button><div class="week-plans">${tasks.filter(t=>t.date===key).sort((a,b)=>a.time.localeCompare(b.time)).map(taskHTML).join('')}<button class="agenda-add" data-new="${key}" aria-label="Add a plan for ${d.toDateString()}">${icon('plus')}</button></div></section>`}).join('')}</div></div></div>`}

function yearWeeks(year){const jan4=new Date(year,0,4),first=new Date(jan4);first.setDate(jan4.getDate()-((jan4.getDay()+6)%7));const next=new Date(year+1,0,4);next.setDate(next.getDate()-((next.getDay()+6)%7));const weeks=[];for(let d=new Date(first),n=1;d<next;d.setDate(d.getDate()+7),n++){const start=new Date(d),end=new Date(d),anchor=new Date(d);end.setDate(d.getDate()+6);anchor.setDate(d.getDate()+3);weeks.push({start,end,month:anchor.getMonth(),n})}return weeks}
function yearHTML(){const year=viewed.getFullYear(),weeks=yearWeeks(year),now=weeks.find(w=>dateKey(w.start)<=dateKey(today)&&dateKey(w.end)>=dateKey(today)),elapsed=year===today.getFullYear()?Math.round((today-new Date(year,0,1))/(new Date(year+1,0,1)-new Date(year,0,1))*100):year<today.getFullYear()?100:0;const annual=data.tasks.filter(t=>visible(t)&&fromKey(t.date).getFullYear()===year);return `<div class="year-summary"><span><b>${now?'Week '+now.n+' of '+weeks.length:year+' at a glance'}</b><span class="muted"> A little progress, every day.</span></span><span>${annual.filter(t=>!t.done).length} open plans · ${elapsed}% of the year</span></div><div class="year-progress"><i style="width:${elapsed}%"></i></div><div class="year-grid">${[0,2,1,3].map(q=>`<section class="quarter"><div class="quarter-heading"><span>Q${q+1} <b>${['Build the foundation','Find your momentum','Make it meaningful','Finish with intention'][q]}</b></span><span>${['JAN — MAR','APR — JUN','JUL — SEP','OCT — DEC'][q]}</span></div>${[0,1,2].map(i=>{const m=q*3+i;return `<div class="month-row"><button class="month-name" data-month="${m}" title="Open ${new Date(year,m,1).toLocaleDateString('en-US',{month:'long'})}">${new Date(year,m,1).toLocaleDateString('en-US',{month:'short'}).toUpperCase()}</button><div class="month-weeks">${weeks.filter(w=>w.month===m).map(w=>{const tasks=annual.filter(t=>t.scope!=='month'&&t.date>=dateKey(w.start)&&t.date<=dateKey(w.end)),isNow=now?.n===w.n;return `<article class="mini-week ${isNow?'is-now':''} ${w.end<today?'past':''}"><button class="week-label" data-week="${dateKey(w.start)}" aria-label="Open week ${w.n}, ${formatDate(dateKey(w.start))}"><b>W${w.n}${isNow?'<em>NOW</em>':''}</b><span>${w.start.getDate()}–${w.end.getDate()} ${w.end.toLocaleDateString('en-US',{month:'short'})}</span></button><div class="week-cells">${Array.from({length:7},(_,j)=>{const d=new Date(w.start);d.setDate(d.getDate()+j);const key=dateKey(d),dayTasks=tasks.filter(t=>t.date===key);return `<button class="year-day ${j>4?'weekend':''} ${key===dateKey(today)?'is-today':''}" data-year-day="${key}" title="${d.toDateString()}${dayTasks.length?' · '+dayTasks.map(t=>t.title).join(', '):' · Click to plan'}" aria-label="${d.toDateString()}, ${dayTasks.length} plans"><span>${d.getDate()}</span>${dayTasks.slice(0,3).map(t=>`<i style="background:${esc(project(t.project).color)}"></i>`).join('')}</button>`}).join('')}</div><button class="week-caption" ${tasks.length?`data-edit="${tasks[0].id}"`:`data-new="${dateKey(w.start)}"`}>${tasks.length?esc(tasks[0].title)+(tasks.length>1?' <span>+'+(tasks.length-1)+'</span>':''):'<span class="empty-caption">+ Add a plan</span>'}</button></article>`}).join('')}</div></div>`}).join('')}</section>`).join('')}</div><div class="year-bottom"><span>${icon('calendar')} Every week is a fresh start. Click a day to plan, or a week to zoom in.</span><span>Monday – Sunday · ISO weeks</span></div><div class="year-goals"><div><span class="eyebrow">THE BIGGER PICTURE</span><h3>Make this year yours.</h3></div>${annual.filter(t=>t.scope==='month').slice(0,3).map(t=>`<button class="year-goal" data-edit="${t.id}"><span class="dot" style="background:${esc(project(t.project).color)}"></span><span>${esc(t.title)}<small>${formatDate(t.date)} · Monthly goal</small></span></button>`).join('')}<button class="secondary" id="year-goal" onclick="openPlan(null,{scope:'month'})">+ Add a goal</button></div>`}
function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='knull-calendar-backup-'+dateKey(today)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Calendar backup downloaded.')}
function openHelp(){modal(`<div class="modal-head"><h2 id="modal-title">A calendar that zooms with you.</h2><button id="close-modal" class="icon-btn" aria-label="Close">${icon('close')}</button></div><div class="help-copy"><p><b>Year</b> — Every week in one place. Click a day to open its hourly schedule. Click W1, W2… to see a full week.</p><p><b>Month</b> — Four chapters with all dates visible, including the final days of longer months.</p><p><b>New plan</b> — Add a daily task, a weekly intention, or a monthly goal. Choose a project to keep things organized.</p><p><b>Stay in control</b> — Plans save automatically in this browser. Export a backup anytime. Use N for a new plan, ⌘/Ctrl K to search, and Escape to close.</p></div>`)}

function render(){const total=monthTasks().filter(t=>!t.done).length;$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark"><i></i><i></i><i></i></span>knull<span style="font-size:18px;color:#a7b797">.</span></div><div class="workspace"><span class="square">${icon('leaf')}</span><span>My workspace</span><span class="tiny" style="margin-left:auto">PERSONAL</span></div><nav class="nav" aria-label="Main navigation"><button data-nav="calendar" class="${nav==='calendar'?'active':''}">${icon('calendar')} My calendar <span class="count">${total}</span></button><button data-nav="tasks" class="${nav==='tasks'?'active':''}">${icon('check')} All plans</button><button data-nav="projects" class="${nav==='projects'?'active':''}">${icon('grid')} Projects</button></nav><div class="section-label">MY PROJECTS<button class="icon-btn" id="new-project" aria-label="Create project">${icon('plus')}</button></div><div>${data.projects.map(p=>`<button class="project-nav ${filter===p.id?'selected':''}" data-project="${p.id}"><span class="dot" style="background:${esc(p.color)}"></span>${esc(p.name)}</button>`).join('')}</div><div class="sidebar-bottom"><div class="rhythm-note">${icon('leaf')}<strong>A little more intention.</strong><p>You don’t have to do it all.<br>Just make room for what matters.</p></div><div class="profile"><div class="avatar">ME</div><div><strong>Your own little space</strong><span>Let’s make good days.</span></div></div></div></aside><main><header class="topbar"><span class="mobile-brand">knull.</span><div class="breadcrumb">Workspace <span>/</span> <b>${nav==='calendar'?'My calendar':nav==='tasks'?'All plans':'Projects'}</b></div><div class="top-actions"><button class="icon-btn" id="help" aria-label="How to use the calendar">How it works</button><button class="icon-btn" id="backup" aria-label="Export calendar backup">Export</button><button class="search-btn" id="search" aria-label="Search plans">${icon('search')} <span>Search anything</span><span class="key">⌘ K</span></button><div style="height:18px;width:1px;background:var(--line)"></div><span class="avatar">ME</span></div></header><div class="page"><div class="intro"><div><div class="eyebrow">LESS NOISE. MORE INTENTION.</div><h1>Your time. Your canvas<span style="color:#9fb38c">.</span></h1><p>See the big picture. Make space for what matters.</p></div><button class="primary" id="new-plan">${icon('plus')} New plan <span class="shortcut" style="opacity:.5;font-size:10px;margin-left:8px">N</span></button></div><nav class="mobile-nav" aria-label="Mobile navigation"><button data-nav="calendar">Calendar</button><button data-nav="tasks">All plans</button><button data-nav="projects">Projects</button><button id="mobile-project">+ Project</button></nav><div class="toolbar"><div class="month-control"><h2>${view==='year'?viewed.getFullYear():monthName(viewed)}</h2><button class="icon-btn" id="prev" aria-label="Previous ${view}">${icon('left')}</button><button class="icon-btn" id="next" aria-label="Next ${view}">${icon('right')}</button><button class="today-btn" id="today">Today</button></div><div class="switcher" role="group" aria-label="Calendar view">${['year','month','week','day'].map(v=>`<button data-view="${v}" class="${view===v&&nav==='calendar'?'active':''}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></div>${filter?`<div class="filter-note">Showing ${esc(project(filter).name)} <button id="clear-filter">Clear filter ×</button></div>`:''}<div class="content-layout ${view==='year'&&nav==='calendar'?'year-layout':''}"><div>${nav==='calendar'&&view==='year'?yearHTML():nav==='projects'?projectsHTML():nav==='tasks'?`<div class="view-panel"><div class="view-heading"><h3>All plans · ${monthName(viewed)}</h3><span class="tiny">${monthTasks().length} plans</span></div><div class="task-list">${monthTasks().sort((a,b)=>a.date.localeCompare(b.date)).map(taskHTML).join('')||'<div class="no-results">No plans yet. Start with something small.</div>'}</div></div>`:view==='month'?`<div class="chapters">${[0,1,2,3].map(chapterHTML).join('')}</div><div class="insight">${icon('leaf')}<span><b>Progress has its own pace.</b> Leave a little breathing room between the plans.</span></div>`:scheduleHTML()}</div>${view==='year'&&nav==='calendar'?'':agendaHTML()}</div><footer class="footer"><span>${icon('cloud')} Saved on this browser · Your pace. Your space.</span><div class="legend">${data.projects.map(p=>`<span><i class="dot" style="background:${esc(p.color)}"></i>${esc(p.name)}</span>`).join('')}</div></footer></div></main></div>`;bind()}
function projectsHTML(){return `<div class="chapters">${data.projects.map(p=>{const tasks=monthTasks().filter(t=>t.project===p.id);return `<section class="chapter"><div class="chapter-head"><h3><span class="dot" style="background:${esc(p.color)};margin-right:7px"></span>${esc(p.name)}</h3><span class="tiny">${tasks.filter(t=>t.done).length}/${tasks.length} done</span></div><div class="chapter-tasks">${tasks.map(taskHTML).join('')||'<div class="empty-week">Room for your next idea.</div>'}</div><button class="add-chapter" data-new-project="${p.id}">${icon('plus')} Add a plan</button></section>`}).join('')}</div>`}
function bind(){document.querySelectorAll('[data-toggle]').forEach(el=>el.onclick=e=>{e.stopPropagation();const t=data.tasks.find(t=>t.id===el.dataset.toggle);t.done=!t.done;save();render()});document.querySelectorAll('[data-edit]').forEach(el=>{el.onclick=()=>openPlan(el.dataset.edit);el.onkeydown=e=>{if(e.key==='Enter'&&e.target===el)openPlan(el.dataset.edit)}});document.querySelectorAll('[data-date]').forEach(el=>el.onclick=()=>{selected=el.dataset.date;viewed=new Date(fromKey(selected).getFullYear(),fromKey(selected).getMonth(),1);render()});document.querySelectorAll('[data-new]').forEach(el=>el.onclick=()=>openPlan(null,{date:el.dataset.new}));document.querySelectorAll('[data-new-project]').forEach(el=>el.onclick=()=>openPlan(null,{project:el.dataset.newProject}));document.querySelectorAll('[data-hour]').forEach(el=>el.onclick=()=>openPlan(null,{date:selected,time:el.dataset.hour}));document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{view=el.dataset.view;nav='calendar';render()});document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>{nav=el.dataset.nav;filter=null;render()});document.querySelectorAll('[data-project]').forEach(el=>el.onclick=()=>{filter=filter===el.dataset.project?null:el.dataset.project;render()});document.querySelectorAll('[data-week]').forEach(el=>el.onclick=()=>{selected=el.dataset.week;viewed=new Date(fromKey(selected).getFullYear(),fromKey(selected).getMonth(),1);view='week';render()});document.querySelectorAll('[data-month]').forEach(el=>el.onclick=()=>{viewed=new Date(viewed.getFullYear(),Number(el.dataset.month),1);selected=dateKey(viewed);view='month';render()});document.querySelectorAll('[data-year-day]').forEach(el=>el.onclick=()=>{selected=el.dataset.yearDay;viewed=new Date(fromKey(selected).getFullYear(),fromKey(selected).getMonth(),1);view='day';render()});$('#backup')?.addEventListener('click',exportData);$('#help')?.addEventListener('click',openHelp);$('#new-plan').onclick=()=>openPlan();$('#new-project').onclick=openProject;$('#mobile-project').onclick=openProject;$('#search').onclick=openSearch;$('#add-goal').onclick=()=>openPlan(null,{date:dateKey(viewed),scope:'month'});$('#clear-filter')?.addEventListener('click',()=>{filter=null;render()});$('#prev').onclick=()=>navigate(-1);$('#next').onclick=()=>navigate(1);$('#today').onclick=()=>{viewed=new Date(today.getFullYear(),today.getMonth(),1);selected=dateKey(today);render()}}
function navigate(n){if(view==='year'&&nav==='calendar'){viewed=new Date(viewed.getFullYear()+n,0,1);selected=dateKey(viewed);render();return}if(view==='month'||nav!=='calendar'){viewed=new Date(viewed.getFullYear(),viewed.getMonth()+n,1);selected=dateKey(viewed)}else{const d=fromKey(selected);d.setDate(d.getDate()+n*(view==='week'?7:1));selected=dateKey(d);viewed=new Date(d.getFullYear(),d.getMonth(),1)}render()}
function modal(html){$('#modal-root').innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${html}</section></div>`;$('.overlay').onclick=e=>{if(e.target===$('.overlay'))closeModal()};$('#close-modal').onclick=closeModal;setTimeout(()=>$('.modal input')?.focus(),20)}
let lastFocus;function closeModal(){$('#modal-root').innerHTML='';lastFocus?.focus?.()}
function openPlan(id=null,preset={}){lastFocus=document.activeElement;const t=id?data.tasks.find(t=>t.id===id):{title:'',date:selected,time:'',project:filter||data.projects[0].id,scope:'day',...preset};modal(`<div class="modal-head"><h2 id="modal-title">${id?'A little fine-tuning':'Make room for a plan'}</h2><button class="icon-btn" id="close-modal" aria-label="Close">${icon('close')}</button></div><form id="plan-form"><label for="title">What’s on your mind?</label><input id="title" name="title" placeholder="Something worth making time for…" value="${esc(t.title)}" required maxlength="160"><div class="form-row"><div><label for="scope">Plan for</label><select id="scope" name="scope">${['day','week','month'].map(s=>`<option value="${s}" ${t.scope===s?'selected':''}>${{day:'A day',week:'A week',month:'The month'}[s]}</option>`).join('')}</select></div><div><label for="project">Project</label><select id="project" name="project">${data.projects.map(p=>`<option value="${p.id}" ${p.id===t.project?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div><div class="form-row"><div><label for="date" id="date-label">${t.scope==='week'?'Week containing':t.scope==='month'?'Month containing':'Date'}</label><input id="date" name="date" type="date" value="${t.date}" required min="1900-01-01" max="9999-12-31"></div><div id="time-field" ${t.scope!=='day'?'hidden':''}><label for="time">Time <span class="tiny">optional</span></label><input id="time" name="time" type="time" value="${t.time}"></div></div><div class="form-actions">${id?'<button type="button" class="danger" id="delete-plan">Delete plan</button>':'<span class="tiny">A small step is still a step.</span>'}<button class="primary" type="submit">${id?'Save changes':'Create plan'} </button></div></form>`);$('#scope').onchange=()=>{$('#time-field').hidden=$('#scope').value!=='day';$('#date-label').textContent=$('#scope').value==='week'?'Week containing':$('#scope').value==='month'?'Month containing':'Date'};$('#plan-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim();if(!title){$('#title').focus();return}const task={id:id||uid(),title,date:f.get('date'),time:f.get('scope')==='day'?f.get('time'):'',scope:f.get('scope'),project:f.get('project'),done:id?t.done:false};if(id)data.tasks=data.tasks.map(x=>x.id===id?task:x);else data.tasks.push(task);selected=task.date;viewed=new Date(fromKey(selected).getFullYear(),fromKey(selected).getMonth(),1);save();closeModal();render();toast(id?'Plan updated. A little clearer.':'A little intention, added.')};$('#delete-plan')?.addEventListener('click',()=>{data.tasks=data.tasks.filter(x=>x.id!==id);save();closeModal();render();toast('Plan removed. A little more space.')})}
function openProject(){lastFocus=document.activeElement;modal(`<div class="modal-head"><h2 id="modal-title">A home for your ideas</h2><button class="icon-btn" id="close-modal" aria-label="Close">${icon('close')}</button></div><form id="project-form"><label for="project-name">Project name</label><input id="project-name" placeholder="A side project, a big dream…" required maxlength="40"><label for="project-color">Color</label><select id="project-color"><option value="purple">Lavender</option><option value="green">Sage</option><option value="orange">Apricot</option><option value="blue">Sky</option></select><div class="form-actions"><span></span><button class="primary">Create project </button></div></form>`);$('#project-form').onsubmit=e=>{e.preventDefault();const name=$('#project-name').value.trim();if(!name)return;const tone=$('#project-color').value;data.projects.push({id:uid(),name,tone,color:{purple:'#a995c8',green:'#9eb589',orange:'#d3a374',blue:'#89a9b6'}[tone]});save();closeModal();render();toast('A new space for your ideas.')}}
function openSearch(){lastFocus=document.activeElement;modal(`<div class="modal-head"><h2 id="modal-title">Find a little clarity</h2><button class="icon-btn" id="close-modal" aria-label="Close">${icon('close')}</button></div><input id="search-input" aria-label="Search all plans" placeholder="Search plans and projects…"><div id="search-results"></div>`);const results=()=>{const q=$('#search-input').value.toLowerCase().trim();const tasks=data.tasks.filter(t=>(t.title+' '+project(t.project).name).toLowerCase().includes(q));$('#search-results').innerHTML=tasks.slice(0,30).map(t=>`<button class="search-result" data-result="${t.id}">${esc(t.title)}<small>${formatDate(t.date)} ${fromKey(t.date).getFullYear()} · ${esc(project(t.project).name)}</small></button>`).join('')||'<div class="no-results">No plans found. Try another word.</div>';document.querySelectorAll('[data-result]').forEach(el=>el.onclick=()=>openPlan(el.dataset.result))};$('#search-input').oninput=results;results()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return}if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();openSearch();return}if($('.modal')){if(e.key==='Tab'){const items=[...$('.modal').querySelectorAll('button,input,select')].filter(el=>!el.closest('[hidden]'));if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus()}}return}if(e.key.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))openPlan()});
save();render();
